namespace PriceCalculatorDemo;

public class PriceCalculator
{
    public decimal CalculateTotal(decimal unitPrice, int quantity)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(unitPrice);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(quantity);

        return unitPrice * quantity;
    }

    public decimal ApplyDiscount(decimal total, decimal discountPercent)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(total);
        if (discountPercent < 0 || discountPercent > 100)
            throw new ArgumentOutOfRangeException(nameof(discountPercent));

        return total - (total * discountPercent / 100m);
    }
}

using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace PriceCalculatorDemo.Tests;

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ─── DataRow: inline compile-time constants ───────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 10.00, DisplayName = "Single item")]
    [DataRow(10.00, 5, 50.00, DisplayName = "Multiple items")]
    [DataRow(0.01, 1, 0.01, DisplayName = "Minimum price")]
    [DataRow(99.99, 100, 9999.00, DisplayName = "Large quantity")]
    public void CalculateTotal_ReturnsExpected(
        double unitPrice, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(0, 1, DisplayName = "Zero price is valid")]
    public void CalculateTotal_ZeroPrice_ReturnsZero(
        double unitPrice, int quantity)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity);

        Assert.AreEqual(0m, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1, DisplayName = "Negative price")]
    public void CalculateTotal_InvalidPrice_Throws(
        double unitPrice, int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity));
    }

    [TestMethod]
    [DataRow(10.00, 0, DisplayName = "Zero quantity")]
    [DataRow(10.00, -1, DisplayName = "Negative quantity")]
    public void CalculateTotal_InvalidQuantity_Throws(
        double unitPrice, int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity));
    }

    // ─── DynamicData: complex/decimal-precise test cases ─────────────

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_ReturnsExpected(
        decimal total, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(total, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> ApplyDiscountCases()
    {
        yield return new object[] { 100m, 0m, 100m };    // No discount
        yield return new object[] { 100m, 10m, 90m };    // 10% off
        yield return new object[] { 100m, 50m, 50m };    // Half off
        yield return new object[] { 100m, 100m, 0m };    // Free
        yield return new object[] { 49.99m, 25m, 37.4925m }; // Fractional result
        yield return new object[] { 0m, 50m, 0m };       // Zero total
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_InvalidInput_Throws(
        decimal total, decimal discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(total, discountPercent));
    }

    public static IEnumerable<object[]> InvalidDiscountCases()
    {
        yield return new object[] { -1m, 10m };   // Negative total
        yield return new object[] { 100m, -1m };  // Negative discount
        yield return new object[] { 100m, 101m }; // Discount > 100%
    }
}

